import { listCustomers } from './customers.js';

/** Quotes a CSV field when it contains a comma, quote or line break. */
function csvField(value) {
  const text = String(value);
  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

/** Returns the customers as CSV text: a "id,name,region" header, then one line per customer, sorted by id. */
export function exportCustomersCsv() {
  // listCustomers() order is not stable in production, so sort by id for a deterministic export.
  const customers = listCustomers().sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  const lines = customers.map((customer) =>
    [customer.id, customer.name, customer.region].map(csvField).join(','),
  );
  return ['id,name,region', ...lines].join('\n');
}

